// Genera ventanas de N días entre `since` y `until`.
// Cada item = un chunk que será una request a Meta con time_increment=1.
const cfg = $input.first().json;
const chunkDays = cfg.chunk_days || 90;

const startMs = new Date(cfg.since + 'T00:00:00Z').getTime();
const endMs = new Date(cfg.until + 'T00:00:00Z').getTime();
const dayMs = 24 * 60 * 60 * 1000;

if (isNaN(startMs) || isNaN(endMs) || startMs > endMs) {
  throw new Error(`Rango inválido: since=${cfg.since}, until=${cfg.until}`);
}

const chunks = [];
let cursor = startMs;
while (cursor <= endMs) {
  const chunkEnd = Math.min(cursor + (chunkDays - 1) * dayMs, endMs);
  chunks.push({
    since: new Date(cursor).toISOString().slice(0, 10),
    until: new Date(chunkEnd).toISOString().slice(0, 10)
  });
  cursor = chunkEnd + dayMs;
}

return chunks.map((c, i) => ({
  json: { ...c, chunk_index: i + 1, chunk_total: chunks.length }
}));

// DUPLICADO con E3A_Meta_Ads_Daily_Sync.json — el bloque de mapeo debe mantenerse idéntico (guard: scripts/check-transform-ads-sync.sh). 'fecha' diverge a propósito.
// Aplana resultados de todas las páginas del chunk y mapea al formato
// esperado por upsert_meta_ads(). Usa ad.date_start como `fecha`.
const items = $input.all();
const ads = [];
for (const it of items) {
  const data = it.json?.data || [];
  for (const ad of data) ads.push(ad);
}

if (ads.length === 0) {
  return [{ json: { ads_data: [], count: 0 } }];
}

const mapped = ads.map(ad => {
  const actions = ad.actions || [];
  const actionValues = ad.action_values || [];

  const findAction = (type) => {
    const found = actions.find(a => a.action_type === type);
    return found ? parseInt(found.value) || 0 : 0;
  };
  const findActionValue = (type) => {
    const found = actionValues.find(a => a.action_type === type);
    return found ? parseFloat(found.value) || 0 : 0;
  };

  return {
    fecha: ad.date_start,
    ad_id: ad.ad_id,
    ad_name: ad.ad_name,
    adset_id: ad.adset_id,
    adset_name: ad.adset_name,
    campaign_id: ad.campaign_id,
    campaign_name: ad.campaign_name,
    creative_asset_id: null,
    es_pagado: true,
    objetivo: ad.objective || null,
    audiencia: ad.adset_name || null,
    impresiones: parseInt(ad.impressions) || 0,
    alcance: parseInt(ad.reach) || 0,
    clics: parseInt(ad.clicks) || 0,
    clics_link: parseInt(ad.inline_link_clicks) || 0,
    gasto: parseFloat(ad.spend) || 0,
    compras: findAction('purchase'),
    valor_compras: findActionValue('purchase'),
    agrega_carrito: findAction('add_to_cart'),
    inicia_checkout: findAction('initiate_checkout'),
    vistas_contenido: findAction('view_content'),
    headline: null,
    body_copy: null,
    cta: null,
    meta_raw_json: ad
  };
});

return [{ json: { ads_data: mapped, count: mapped.length } }];
